import { spawn } from 'node:child_process';
import { existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

// Board sounds are generated by scripts/sounds/generate.mjs and ship with the service copy.
export const BOARD_SOUNDS = Object.freeze(['pop', 'droplet', 'tick', 'chime', 'marimba', 'bell', 'ping', 'alarm', 'siren', 'klaxon', 'redalert']);
export const MAC_SOUNDS = Object.freeze(['Basso', 'Blow', 'Bottle', 'Frog', 'Funk', 'Glass', 'Hero', 'Morse', 'Ping', 'Pop', 'Purr', 'Sosumi', 'Submarine', 'Tink']);
export const SOUND_IDS = Object.freeze(['none', ...BOARD_SOUNDS.map((name) => `board:${name}`), ...MAC_SOUNDS.map((name) => `mac:${name}`)]);

const SOUNDS_DIR = join(dirname(fileURLToPath(import.meta.url)), 'sounds');
const MAC_DIR = '/System/Library/Sounds';

export function soundFile(id) {
  const [kind, name] = String(id).split(':');
  if (kind === 'board' && BOARD_SOUNDS.includes(name)) return join(SOUNDS_DIR, `${name}.wav`);
  if (kind === 'mac' && MAC_SOUNDS.includes(name)) return join(MAC_DIR, `${name}.aiff`);
  return null;
}

export function listSounds({ platform = process.platform } = {}) {
  return SOUND_IDS.filter((id) => id !== 'none').map((id) => {
    const file = soundFile(id);
    const kind = id.split(':')[0];
    return { id, kind, available: Boolean(file) && (kind === 'board' || platform === 'darwin') && existsSync(file) };
  });
}

// Fire and forget: a missing player or file must never break the service.
function run(cmd, args, spawnFn) {
  try {
    const child = spawnFn(cmd, args, { detached: true, stdio: 'ignore' });
    child.on?.('error', () => {});
    child.unref?.();
    return true;
  } catch {
    return false;
  }
}

export function playSound(id, { volume = 70, platform = process.platform, spawnFn = spawn } = {}) {
  const file = soundFile(id);
  if (!file) return false;
  const level = Math.max(0, Math.min(100, Number(volume) || 0)) / 100;
  if (level === 0) return false;
  if (platform === 'darwin') return run('afplay', ['-v', level.toFixed(2), file], spawnFn);
  if (platform === 'linux' && id.startsWith('board:')) return run('paplay', [`--volume=${Math.round(level * 65536)}`, file], spawnFn);
  return false;
}

const appleString = (text) => `"${String(text).replace(/[\\"]/g, '\\$&').replace(/[\r\n]+/g, ' ')}"`;

export function showBanner(title, body, { platform = process.platform, spawnFn = spawn } = {}) {
  if (platform === 'darwin') {
    return run('osascript', ['-e', `display notification ${appleString(body)} with title ${appleString(title)}`], spawnFn);
  }
  if (platform === 'linux') return run('notify-send', ['--app-name=EpicBoard', String(title), String(body)], spawnFn);
  return false;
}
